    "reason": "The source states that early stopping uses validation performance to decide when to end training but does not explain the specific mechanism or trend (e.g., divergence of validation error) that signals the onset of overfitting."
  },
  "question_0013": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source defines overfitting by the discrepancy between training and unseen performance but does not describe the internal changes in representations or decision boundaries that characterize this state."
  },
  "question_0014": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source mentions that a retrieval encoder maps questions and passages into embeddings but does not explain the internal mechanism (e.g., network architecture or mathematical operations) used to perform this mapping."
  },
  "question_0015": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source states that embeddings are created but does not specify which properties (syntactic, semantic, or both) of the questions and passages are captured during this process."
  },
  "question_0016": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source states that a similarity search selects candidate passages but does not specify the metric or distance function (e.g., cosine similarity) used for this selection."
  },
  "question_0017": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source states that selected passages are added to the context but does not explain the specific integration method (e.g., concatenation, token insertion) used."
  },
  "question_0018": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source lists 'irrelevant', 'outdated', or 'incorrect' as possible states for highly ranked passages but does not define the specific criteria or indicators used to determine these states."
  },
  "question_0019": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source states that updating the document index makes revised material available but does not describe the specific procedure (e.g., re-indexing, incremental updates) used to perform this update."
  },
  "question_0020": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source implies a distinction between citing a passage and making a supported claim but does not explain the specific criteria or methods used to determine if an answer is actually supported versus merely cited."
  },
  "question_0021": {
    "answered": false,
    "evidence_ids": [],
    "reason": "The source mentions that missing evidence does not prove falsity and lists types of retrieval failures but does not explain the logic or thresholds used to differentiate between irrelevant/outdated/incorrect passages and those that simply fail to support a specific claim."
  }
}
